.asciz "#ifdef NANOVG_GL3\n\tuniform vec2 viewSize;\n\tin vec2 vertex;\n\tin vec2 tcoord;\n\tout vec2 ftcoord;\n\tout vec2 fpos;\n#else\n\tuniform vec2 viewSize;\n\tattribute vec2 vertex;\n\tattribute vec2 tcoord;\n\tvarying vec2 ftcoord;\n\tvarying vec2 fpos;\n#endif\nvoid main(void) {\n\tftcoord = tcoord;\n\tfpos = vertex;\n\tgl_Position = vec4(2.0*vertex.x/viewSize.x - 1.0, 1.0 - 2.0*vertex.y/viewSize.y, 0, 1);\n}\n"
.asciz "#ifdef GL_ES\n#if defined(GL_FRAGMENT_PRECISION_HIGH) || defined(NANOVG_GL3)\n precision highp float;\n#else\n precision mediump float;\n#endif\n#endif\n#ifdef NANOVG_GL3\n#ifdef USE_UNIFORMBUFFER\n\tlayout(std140) uniform frag {\n\t\tmat3 scissorMat;\n\t\tmat3 paintMat;\n\t\tvec4 innerCol;\n\t\tvec4 outerCol;\n\t\tvec2 scissorExt;\n\t\tvec2 scissorScale;\n\t\tvec2 extent;\n\t\tfloat radius;\n\t\tfloat feather;\n\t\tfloat strokeMult;\n\t\tfloat strokeThr;\n\t\tint texType;\n\t\tint type;\n\t};\n#else\n\tuniform vec4 frag[UNIFORMARRAY_SIZE];\n#endif\n\tuniform sampler2D tex;\n\tin vec2 ftcoord;\n\tin vec2 fpos;\n\tout vec4 outColor;\n#else\n\tuniform vec4 frag[UNIFORMARRAY_SIZE];\n\tuniform sampler2D tex;\n\tvarying vec2 ftcoord;\n\tvarying vec2 fpos;\n#endif\n#ifndef USE_UNIFORMBUFFER\n\t#define scissorMat mat3(frag[0].xyz, frag[1].xyz, frag[2].xyz)\n\t#define paintMat mat3(frag[3].xyz, frag[4].xyz, frag[5].xyz)\n\t#define innerCol frag[6]\n\t#define outerCol frag[7]\n\t#define scissorExt frag[8].xy\n\t#define scissorScale frag[8].zw\n\t#define extent frag[9].xy\n\t#define radius frag[9].z\n\t#define feather frag[9].w\n\t#define strokeMult frag[10].x\n\t#define strokeThr frag[10].y\n\t#define texType int(frag[10].z)\n\t#define type int(frag[10].w)\n#endif\n\nfloat sdroundrect(vec2 pt, vec2 ext, float rad) {\n\tvec2 ext2 = ext - vec2(rad,rad);\n\tvec2 d = abs(pt) - ext2;\n\treturn min(max(d.x,d.y),0.0) + length(max(d,0.0)) - rad;\n}\n\n// Scissoring\nfloat scissorMask(vec2 p) {\n\tvec2 sc = (abs((scissorMat * vec3(p,1.0)).xy) - scissorExt);\n\tsc = vec2(0.5,0.5) - sc * scissorScale;\n\treturn clamp(sc.x,0.0,1.0) * clamp(sc.y,0.0,1.0);\n}\n#ifdef EDGE_AA\n// Stroke - from [0..1] to clipped pyramid, where the slope is 1px.\nfloat strokeMask() {\n\treturn min(1.0, (1.0-abs(ftcoord.x*2.0-1.0))*strokeMult) * min(1.0, ftcoord.y);\n}\n#endif\n\nvoid main(void) {\n   vec4 result;\n\tfloat scissor = scissorMask(fpos);\n#ifdef EDGE_AA\n\tfloat strokeAlpha = strokeMask();\n\tif (strokeAlpha < strokeThr) discard;\n#else\n\tfloat strokeAlpha = 1.0;\n#endif\n\tif (type == 0) {\t\t\t// Gradient\n\t\t// Calculate gradient color using box gradient\n\t\tvec2 pt = (paintMat * vec3(fpos,1.0)).xy;\n\t\tfloat d = clamp((sdroundrect(pt, extent, radius) + feather*0.5) / feather, 0.0, 1.0);\n\t\tvec4 color = mix(innerCol,outerCol,d);\n\t\t// Combine alpha\n\t\tcolor *= strokeAlpha * scissor;\n\t\tresult = color;\n\t} else if (type == 1) {\t\t// Image\n\t\t// Calculate color fron texture\n\t\tvec2 pt = (paintMat * vec3(fpos,1.0)).xy / extent;\n#ifdef NANOVG_GL3\n\t\tvec4 color = texture(tex, pt);\n#else\n\t\tvec4 color = texture2D(tex, pt);\n#endif\n\t\tif (texType == 1) color = vec4(color.xyz*color.w,color.w);\t\tif (texType == 2) color = vec4(color.x);\t\t// Apply color tint and alpha.\n\t\tcolor *= innerCol;\n\t\t// Combine alpha\n\t\tcolor *= strokeAlpha * scissor;\n\t\tresult = color;\n\t} else if (type == 2) {\t\t// Stencil fill\n\t\tresult = vec4(1,1,1,1);\n\t} else if (type == 3) {\t\t// Textured tris\n#ifdef NANOVG_GL3\n\t\tvec4 color = texture(tex, ftcoord);\n#else\n\t\tvec4 color = texture2D(tex, ftcoord);\n#endif\n\t\tif (texType == 1) color = vec4(color.xyz*color.w,color.w);\t\tif (texType == 2) color = vec4(color.x);\t\tcolor *= scissor;\n\t\tresult = color * innerCol;\n\t}\n#ifdef NANOVG_GL3\n\toutColor = result;\n#else\n\tgl_FragColor = result;\n#endif\n}\n"
